#!/usr/bin/env python3
"""Reader-facing report and fixed descriptive figures; no model fitting."""
from pathlib import Path
from fractions import Fraction
import csv,json
import numpy as np
P=Path(__file__).resolve().parent
R=json.loads((P/'results.json').read_text());DC=json.loads((P/'decision_certificates.json').read_text());CW=json.loads((P/'classification_witnesses.json').read_text());V=json.loads((P/'verification.json').read_text())

rows=[]
for r in R['results']:
 for bn,b in r['banks'].items():
  for name,d in b['results'].items():
   rows.append({'seed':r['seed'],'architecture':r['architecture'],'bank':bn,'method':name,'mse_sum_outputs':d['prediction']['mse_sum_outputs'],'max_absolute_error':d['prediction']['max_abs'],'fraction_within_epsilon1':d['prediction']['within_epsilon']['1.0'],'state_bits':d.get('state_bits',r['methods'].get(name,{}).get('state_bits')),'action_selection_accuracy_at_three_quarters':d.get('policy',{}).get('best_group_accuracy'),'mean_action_regret':d.get('policy',{}).get('mean_action_regret'),'p95_action_regret':d.get('policy',{}).get('p95_action_regret')})
with (P/'all_metrics.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=rows[0]);w.writeheader();w.writerows(rows)

lines=['# Predicting actions from the original report','',
'This exploratory study asks whether a report computed **before an intervention** suffices to predict its effects. It reuses all six trained checkpoints and the previously inspected digit splits. No neural model is retrained. “Prospective” describes the timing of the prediction query; this study is retrospective and is not preregistered or evaluated on a new pristine holdout.','',
'## A stricter information interface','',
'The previous experiments supplied both T(h) and T(h′) to the response predictor. Here the report encoder sees only h. A query supplies the fixed group action and attenuation strength, and the decoder must predict F(h′)−F(h) without seeing or computing the true post-action state h′. The four groups are the same fixed eight-unit subsets used previously. All four action effects are evaluated for each image.','',
'We retain native8, native12, PCA8 and the nonlinear model’s random8 report maps. The shallow random8 maps are a new exploratory control: 32 seeded Gaussian candidate directions receive the same original retrospective discovery selection procedure as the other report families. We also encode the current centered output through the existing box quantiser: this costs 77 state bits for each shallow model, and 89, 89 and 88 bits for the three nonlinear models. It still sees only the original state. Computing current outputs in the encoder is explicitly charged; it is not counted as a semantic explanation.','',
'A common prospective decoder has the fixed form s B_g[1,z]+s(1−s) G_g[1,z], where z is a standardized report, g is the group and s the strength. This is affine in the report and quadratic in strength. It is trained at strengths 1/2 and 1 on discovery-fit images; ridge is chosen on the original separate discovery-validation images. It is evaluated at those strengths and at 1/4 and 3/4. Standardization uses discovery-fit codes only. The polynomial is a predetermined limited model, not an exact assumption about the nonlinear classifier.','',
'This decoder has 80(d+1) coefficients for a d-coordinate report: 720 for native8/PCA8/random8, 1,040 for native12, 880 for the ten-coordinate current-output quantiser, and 80 for the action-only baseline. This is substantially more permissive than the earlier shared report-difference decoder. Errors should not be compared across those studies as if only the information timing had changed.','',
'A single query additionally requires 4 action bits to specify one of four groups and four strengths. Native8 therefore uses 12 query bits; the shallow current-output code uses 81. The margin-action decision described below supplies a further ordered top/runner class pair, at most 7 bits. No exact current margin, image identity, digit label, or true post-action report is supplied. The current-output encoder uses the known downstream computation (320 centered head coefficients for the shallow model, 698 weights/biases for the nonlinear model), in addition to scalar quantiser constants. Dense PCA/random8 needs at most 256 projection coefficients; native8 uses eight coordinate predicates.','',
'## Measured response prediction','',
'MSE sums squared error over ten centered logits, then averages the 2,912 image/action rows in each bank. Images within a model and their repeated interventions are dependent. These are descriptive observations on the reused split.','',
'| Seed | Downstream readout | Native8 unseen MSE | Native12 | PCA8 | Random8 | Current output | Action only |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in R['results']:
 b=r['banks']['unseen_strength']['results'];lines.append(f"|{r['seed']}|{r['architecture']}|"+'|'.join(f"{b[n]['prediction']['mse_sum_outputs']:.3f}" for n in ['native-8','native-12','pca-8','random-8','current-output','action-only'])+'|')
lines+=['','Current-output reports predict these natural-image action effects substantially better than the tested low-bit reports, but use more report bits and an encoder that runs the downstream computation. Their maximum unseen-strength errors are '+', '.join(f"{r['banks']['unseen_strength']['results']['current-output']['prediction']['max_abs']:.3f}" for r in R['results'])+' in seed order 17,29,43,117,129,143, so this fitted decoder does not meet epsilon1. This fitted failure does not itself prove an information obstruction: all 364 current-output codes are distinct on each observed natural-image bank, and the finite lookup oracle has zero error there.','',
'The separate exact action-closure analysis supplies the stronger structural statement for the shallow models: the current centered output has rank 9, whereas a linear state summary sufficient for all four group effects must have rank at least 32. That analysis constructs admissible continuous input pairs with identical current output and different same-action responses. Those exact synthetic witnesses are distinct from the natural-image decision witnesses below; neither should be represented as a natural-data prevalence estimate.','',
'The retained native-coordinate precision codes provide a costed prospective numerical control. Their decoder reconstructs an approximate original state from the code, applies the action to that reconstruction, and evaluates the known downstream model. It never accesses the true future state. The existing global bounds remain sufficient, and every evaluated response passes epsilon1 by exact arithmetic. This is an explicit numerical simulator using 212–287 state bits and the original downstream computation, not a semantic mechanism discovered by the experiment.','',
'## Natural-image decision failures','',
'For a fixed 75% attenuation, define the action’s value as its decrease in the original top-class-versus-runner-up margin. Given only the report and the two class labels, choose one of the four groups to maximize that decrease. This is a concrete targeted intervention question; it is not equivalent to finding any intervention that changes the full ten-way predicted class.','',
'Two images with the same report and the same ordered class pair force any deterministic report-based policy to choose the same group. Let R_ig be the regret of choosing group g on image i: the best attainable margin drop on that image minus the chosen group’s drop. For a report/context fibre, the exact smallest possible worst-case regret is min_g max_i R_ig. The empirical mean-regret floor is obtained by minimizing the sum in each fibre. Both quantities are computed by exhaustive enumeration of four actions using integer response numerators. The worst-case values below concern deterministic policies; a randomized minimax policy defines a different optimization.','',
'| Seed | Native8 minimum worst-case regret | Empirical minimum mean regret | Fitted policy action accuracy | Fitted mean regret |','|---|---:|---:|---:|---:|']
for r in R['results']:
 d=next(x for x in DC['records'] if x['seed']==r['seed'] and x['method']=='native-8');po=r['banks']['unseen_strength']['results']['native-8']['policy'];lines.append(f"|{r['seed']}|{d['minimum_worst_case_regret']:.4f}|{d['empirical_minimum_mean_regret']:.4f}|{100*po['best_group_accuracy']:.2f}%|{po['mean_action_regret']:.4f}|")
lines+=['','Each worst-case native8 bound is attained by a two-image certificate with identical report/context and different unique best actions. The mean floors are much smaller than the tail bounds. These examples demonstrate consequential possible failures on the finite bank; they do not establish that such failures dominate average behaviour. The empirical optimal lookup policies use observed outcomes and are diagnostic oracles, not deployed explainers.','',
'## Fixed classification illustrations','',
'The following examples were selected descriptively from the exact native8 certificates. Their 75% action strength and top/runner-margin objective were fixed before this illustration; no action strength or margin threshold was searched to manufacture a classification change.','',
'**Shallow seed 43: a classification-changing action must differ.** Two naturally occurring digit 8 images, 1305 and 253, have the same native8 code and the same predicted class 8 and runner-up 1. Their original margins are 5.17655 and 4.53109. Only action 2 changes the first prediction 8→1; only action 3 changes the second 8→1. Any deterministic policy restricted to the common report/context therefore fails to select a class-flipping action for at least one of these images, although each has such an action. Under a uniform distribution on this particular pair, its success rate is at most 1/2. This is a pair-specific claim, not the test-set failure rate.','',
'| Seed 43 image | Original 8−1 margin | After action 0 | After action 1 | After action 2 | After action 3 | Full predicted classes after 0–3 |','|---|---:|---:|---:|---:|---:|---|']
for cw in CW['cases']:
 if cw['seed']!=43:continue
 for a in cw['cases']:lines.append(f"|{a['image_id']}|{a['baseline_top_runner_margin']:.5f}|"+'|'.join(f'{x:.5f}' for x in a['after_top_runner_margins'])+'|'+str(a['after_predicted_classes'])+'|')
lines+=['','**Nonlinear seed 143: the largest margin-regret certificate is target-specific.** Images 1120 and 11 are both labelled 1, with common predicted class 1 and runner-up 8. Their shared report is 11011010. The unique best groups for reducing the 1−8 margin are 1 and 3, and every common deterministic action incurs at least 4.872248814 margin-regret on one image. However, action 1 changes the full prediction of both images, to 7 and 3 respectively. The different best margin actions therefore do not establish different necessary class-flip actions in this pair. Other classes matter.','',
'| Seed 143 image | Original 1−8 margin | After action 0 | After action 1 | After action 2 | After action 3 | Full predicted classes after 0–3 |','|---|---:|---:|---:|---:|---:|---|']
for cw in CW['cases']:
 if cw['seed']!=143:continue
 for a in cw['cases']:lines.append(f"|{a['image_id']}|{a['baseline_top_runner_margin']:.5f}|"+'|'.join(f'{x:.5f}' for x in a['after_top_runner_margins'])+'|'+str(a['after_predicted_classes'])+'|')
lines+=['','The figures display the images, all four exact margin drops, the actual predicted class after each action, and the finite-pair certificate. No neuron is assigned an unsupported semantic label such as a particular stroke detector.','',
'## Evidence limits and reproduction','',
'The audit repairs an important interface loophole by preventing the decoder from inspecting the actual post-action report. It also translates some report failures into a specified intervention decision on real images. Nevertheless, this remains six small models on one reused dataset. Models, action groups and hypotheses were not independently replicated; neither human interpretability nor larger-network coverage was tested. A good response simulator can move substantial computation into its encoder or decoder. All such costs are therefore retained.','',
f'The independent same-team integer check passed {V["checks"]} checks and replayed all {V["response_rows_replayed"]:,} response rows. It rebuilt every saved fitted prediction from the original code and action only, replayed precision predictions from approximate state only, and exhaustively rechecked every mean/worst decision-regret certificate. The files audit.py, decision_certificates.py, verify.py, results.json, decision_certificates.json and classification_witnesses.json contain the analysis and exact receipts. All source checkpoints and original reports are referenced in the sibling application and nonlinear_application directories, which must remain bundled.','',
'The study does not by itself establish field-leading significance or any broader generality. Its contribution is a scoped, executable failure-and-decision test, with explicit separation of empirical prediction, exact finite obstruction, reachable synthetic aliases and wider generalization.']
(P/'report.md').write_text('\n'.join(lines)+'\n')

def make_figure(seed):
 import matplotlib
 matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 from matplotlib.gridspec import GridSpec
 te=np.load(P.parent/'application'/'test.npz');lookup={int(i):j for j,i in enumerate(te['ids'])};record=next(c for c in CW['cases'] if c['seed']==seed);w=record['certificate'];c=w['same_top_class'];runner=w['same_runner_class'];code=''.join(str(int(x)) for x in w['same_report_code'])
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'pdf.fonttype':42})
 fig=plt.figure(figsize=(11.2,7.8));gs=GridSpec(2,2,figure=fig,height_ratios=[1.05,1.0],left=.09,right=.97,bottom=.19,top=.80,hspace=.38,wspace=.25)
 fig.suptitle('Same report, different best margin interventions',fontsize=16,fontweight='bold',x=.53,y=.985)
 fig.text(.53,.936,f'{record["architecture"].capitalize()} downstream readout, seed {seed}  ·  75% attenuation of a fixed eight-unit group',ha='center',fontsize=10.5)
 fig.text(.53,.902,f'Identical state code: {code}     |     Predicted class: {c}     |     Runner-up: {runner}',ha='center',fontsize=11,bbox={'boxstyle':'round,pad=.4','facecolor':'#e8eef1','edgecolor':'none'})
 for j,a in enumerate(record['cases']):
  ax=fig.add_subplot(gs[0,j]);x=te['x'][lookup[a['image_id']]].reshape(8,8);ax.imshow(x,cmap='gray_r',vmin=0,vmax=16,interpolation='nearest');ax.axis('off');ax.set_title(f'Image {a["image_id"]}  ·  labelled {a["digit_label"]}\nOriginal margin {c}−{runner}: {a["baseline_top_runner_margin"]:.3f}',fontsize=11,pad=8)
  ax=fig.add_subplot(gs[1,j]);drops=np.asarray(w['true_margin_drops'][j]);best=int(np.argmax(drops));colors=['#a8c5cd']*4;colors[best]='#17647b'
  ax.bar(range(4),drops,color=colors,width=.63);ax.axhline(0,color='#69737b',linewidth=.8);ax.axhline(a['baseline_top_runner_margin'],color='#9c4262',linewidth=1.1,linestyle='--');ax.set_xticks(range(4),[f'Action {g}\npred. {k}' for g,k in enumerate(a['after_predicted_classes'])]);ax.tick_params(axis='x',length=0);ax.set_ylabel(f'Decrease in margin {c}−{runner}');ax.set_ylim(min(-7,float(drops.min())-2),max(14,float(drops.max())+2))
  for g,val in enumerate(drops):ax.text(g,val+(.3 if val>=0 else -.35),f'{val:.2f}',ha='center',va='bottom' if val>=0 else 'top',fontsize=9,fontweight='bold' if g==best else 'normal')
  ax.text(.99,.97,'Dashed: original margin',ha='right',va='top',transform=ax.transAxes,color='#9c4262',fontsize=8,bbox={'facecolor':'white','edgecolor':'none','pad':1.5})
 rho=Fraction(w['any_common_action_worst_regret_exact']);lower=(rho.numerator*1000000)//rho.denominator/1000000
 fig.text(.53,.112,f'Exact finite-pair certificate: every common deterministic action has worst-case margin-regret ≥ {lower:.6f}.',ha='center',fontsize=10,fontweight='bold')
 if seed==143:footer='The objective is the fixed 1−8 margin. Action 1 changes both full predictions via other classes (7 and 3).\nThis pair therefore certifies margin regret, not different necessary class-flip actions.'
 else:footer='Only action 2 flips the first image from 8 to 1; only action 3 flips the second.\nA policy using only the identical report and class-pair context cannot choose differently for the two inputs.'
 fig.text(.53,.063,footer,ha='center',va='center',fontsize=9,color='#39444c');fig.text(.53,.017,'Descriptive natural-image pair from a reused test split; not a population estimate. Groups and strength are fixed. No semantic neuron labels are claimed.',ha='center',fontsize=8,color='#59646c')
 fig.savefig(P/f'prospective-decision-seed{seed}.png',dpi=220);fig.savefig(P/f'prospective-decision-seed{seed}.pdf');plt.close(fig)
for seed in [143,43]:make_figure(seed)
print(json.dumps({'report':str(P/'report.md'),'metric_rows':len(rows),'figures':['prospective-decision-seed143','prospective-decision-seed43']}))
